import { defineComponent, h, onMounted, onUnmounted, ref } from "vue";

import { syncSpinPhase } from "./spinner-primitive";

import "./spinner.css";

/**
 * Spinner, a port of opencode's Loader (`@opencode/ui`, `feedback/loader`): a
 * 16px ring with `role="status"` and `aria-label="Loading"`. Size it with
 * `width`/`height` or a class; colour it with `color`. Inside something that
 * already says it is busy (a Button with `aria-busy`), pass
 * `aria-hidden="true"` and it drops its role and label.
 */

export const Spinner = defineComponent({
  name: "Spinner",
  props: {
    width: { type: [Number, String], default: 16 },
    height: { type: [Number, String], default: 16 },
  },
  setup(props, { attrs }) {
    // Every spinner turns in step and one out of view pauses (spinner-primitive.ts).
    const el = ref<SVGSVGElement>();
    let stop: (() => void) | undefined;
    onMounted(() => {
      if (el.value) stop = syncSpinPhase(el.value);
    });
    onUnmounted(() => stop?.());

    return () => {
      const hidden = attrs["aria-hidden"] === true || attrs["aria-hidden"] === "true";

      return h(
        "svg",
        {
          ...attrs,
          ref: el,
          width: props.width,
          height: props.height,
          viewBox: "0 0 16 16",
          fill: "none",
          xmlns: "http://www.w3.org/2000/svg",
          "data-slot": "spinner",
          role: hidden ? undefined : (attrs.role ?? "status"),
          "aria-label": hidden ? undefined : (attrs["aria-label"] ?? "Loading"),
          "aria-hidden": hidden ? "true" : undefined,
        },
        [
          h("circle", { cx: 8, cy: 8, r: 6, "data-slot": "spinner-track", "stroke-width": 2 }),
          h("circle", {
            cx: 8,
            cy: 8,
            r: 6,
            "data-slot": "spinner-indicator",
            pathLength: 100,
            "stroke-width": 2,
            "stroke-dasharray": "33 67",
          }),
        ],
      );
    };
  },
  inheritAttrs: false,
});

import { definePrimitive } from "@ui-sdk/core";

/**
 * Spinner's phase sync, on `@ui-sdk/core` so every framework binding shares
 * it. A port of opencode's `syncSpinPhase` (`@opencode/ui`,
 * packages/ui/src/hooks/spin-phase.ts, MIT), which its Loader uses as a ref.
 *
 * Every spinner on screen turns in step: each infinite CSS animation inside a
 * bound element starts at the document timeline's origin, so two spinners
 * that mount at different times still line up. A spinner scrolled or clipped
 * out of view, under `display: none` or sized to nothing gets
 * `data-offscreen`, which spinner.css uses to pause it; coming back, it
 * resumes and re-pins to the shared phase.
 *
 * Upstream's only Solid-specific part is `onCleanup`; here `syncSpinPhase`
 * returns its cleanup, so it is a slot's `bind` and also works on its own (a
 * Svelte action, a plain element).
 */

let resize: ResizeObserver | undefined;
let visibility: IntersectionObserver | undefined;

// Created on first use, so server rendering never touches these globals.
function observers() {
  // ResizeObserver delivers after style and layout but before paint, so a
  // spinner that mounts or leaves `display: none` (which restarts its CSS
  // animation) paints its first frame already in phase.
  resize ??=
    typeof ResizeObserver === "undefined"
      ? undefined
      : new ResizeObserver((entries) => entries.forEach((entry) => pinVisible(entry.target)));

  // `visibility: hidden` and `opacity: 0` still count as visible.
  visibility ??=
    typeof IntersectionObserver === "undefined"
      ? undefined
      : new IntersectionObserver((entries) =>
          entries.forEach((entry) => {
            entry.target.toggleAttribute("data-offscreen", !entry.isIntersecting);
            pinVisible(entry.target);
          }),
        );

  return { resize, visibility };
}

/** Keeps `el`'s looping animations in the shared phase. Returns the cleanup. */
export function syncSpinPhase(el: Element): () => void {
  const { resize, visibility } = observers();
  const restart = () => pinVisible(el);

  resize?.observe(el);
  visibility?.observe(el);
  // Turning reduced motion back off restarts the animation without resizing anything.
  el.addEventListener("animationstart", restart);

  return () => {
    resize?.unobserve(el);
    visibility?.unobserve(el);
    el.removeEventListener("animationstart", restart);
  };
}

// Setting the start time of a paused CSS animation resumes it and makes it
// ignore `animation-play-state` from then on, so a paused spinner is left
// alone until it is visible. `getAnimations` flushes style, so a spinner that
// has just lost `data-offscreen` is running again by the time it is pinned.
function pinVisible(el: Element) {
  if (el.hasAttribute("data-offscreen")) return;

  pinSpinPhase(el);
}

// Starting every infinite loop at the document timeline's origin puts all
// instances of one animation in phase.
export function pinSpinPhase(el: Element) {
  el.getAnimations({ subtree: true })
    .filter(
      (animation) =>
        animation.effect?.getTiming().iterations === Infinity && animation.startTime !== 0,
    )
    .forEach((animation) => {
      animation.startTime = 0;
    });
}

/** The Spinner root as a ui-sdk part: binding it runs `syncSpinPhase`. */
export const spinnerPrimitive = definePrimitive({
  name: "spinner",
  options: {},
  state: () => ({}),
  api: () => ({}),
  slots: (slot) => ({
    root: slot({
      // Spinner keeps spinner.css's slot, so every binding styles it unchanged.
      attrs: () => ({ "data-slot": "spinner" }),
      bind: (el) => syncSpinPhase(el),
    }),
  }),
});

/*
 * 1:1 port of opencode's Loader (`@opencode/ui`, MIT):
 * packages/ui/src/feedback/loader/loader.css. The console renders this exact
 * ring (its button chunk ships `[data-component="loader-v2"]`): a 16px circle
 * with a 20% track and a third of the ring in full colour, turning every 900ms.
 *
 * Only the selectors changed:
 *
 *   [data-component="loader-v2"]          →  [data-slot="spinner"]
 *   [data-slot="loader-v2-background"]    →  [data-slot="spinner-track"]
 *   [data-slot="loader-v2-progress"]      →  [data-slot="spinner-indicator"]
 *   @keyframes loader-v2-spin             →  spinner-spin
 *   :root[data-motion="reduce"] { … }     →  unnested, plus the OS preference
 *
 * The `color` fallback (#808080) is dropped: --v2-icon-icon-muted always
 * exists, so the colour stays a token. Inside a Button, button.css sets svg
 * colour to currentColor, so the ring takes the label's colour there, as
 * upstream's icon slot does.
 *
 * Not ported: `components/spinner.{tsx,css}`, the "Soft Radar" dot grid that
 * opencode's app shows for AI activity. The console does not ship it.
 *
 * Kitsaas addition, marked below: `prefers-reduced-motion` stops the turn too,
 * like `:root[data-motion="reduce"]`. The ring stays, frozen with its arc at
 * the top, so it still reads as a loading indicator.
 */

@layer components {
  [data-slot="spinner"] {
    --_duration: 900ms;
    display: block;
    flex-shrink: 0;
    color: var(--v2-icon-icon-muted);
    animation: spinner-spin var(--_duration) linear infinite;
    transform-origin: center;
  }

  [data-slot="spinner"] [data-slot="spinner-track"] {
    stroke: currentColor;
    opacity: 0.2;
  }

  [data-slot="spinner"] [data-slot="spinner-indicator"] {
    stroke: currentColor;
    stroke-linecap: round;
    transform: rotate(-90deg);
    transform-origin: center;
  }

  @keyframes spinner-spin {
    to {
      transform: rotate(360deg);
    }
  }

  :root[data-motion="reduce"] [data-slot="spinner"] {
    animation: none;
  }

  /* Kitsaas addition: the OS preference as well as the app-level switch. */
  @media (prefers-reduced-motion: reduce) {
    [data-slot="spinner"] {
      animation: none;
    }
  }

  /* Kitsaas addition: pause while out of view (spinner-primitive.ts sets
     data-offscreen), as upstream does for its dot spinner. */
  [data-slot="spinner"][data-offscreen] {
    animation-play-state: paused;
  }
}
